      .on('postgres_changes', { event: '*', schema: 'public', table: 'workforce' }, (payload) => {
        if (payload.eventType === 'UPDATE') {
          setMembers(prev => prev.map(m => m.id === payload.new.id ? { ...m, ...payload.new } : m));
        }
      })
      .subscribe

